908	function parseJsonObject(text: string): Record<string, unknown> {
909	  let payload: unknown;
910	  try {
911	    payload = JSON.parse(text);
912	  } catch (error) {
913	    throw new HttpError(400, `invalid JSON: ${(error as Error).message}`);
914	  }
915	  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
916	    throw new HttpError(400, 'request body must be a JSON object');
917	  }
918	  return payload as Record<string, unknown>;
919	}
920	
921	function validateDraftInput(data: Record<string, unknown>): DraftInput {
922	  if (typeof data.title !== 'string') {
923	    throw new HttpError(400, 'title must be a string');
924	  }
925	  const title = data.title.trim();
926	  if (title.length === 0) {
927	    throw new HttpError(400, 'title must not be empty or only whitespace');
928	  }
929	  let summary = '';
930	  if (Object.prototype.hasOwnProperty.call(data, 'summary')) {
931	    if (typeof data.summary !== 'string') throw new HttpError(400, 'summary must be a string when provided');
932	    summary = data.summary;
933	  }
934	  if (typeof data.body !== 'string') {
935	    throw new HttpError(400, 'body must be a string');
936	  }
937	  return { title, summary, body: data.body };
938	}
939	
940	// Updates carry the version the editor loaded; stale versions are rejected.
941	// As with creation, summary may be omitted (saved as empty string) but a
942	// present non-string summary is a 400.
943	function validateUpdateInput(data: Record<string, unknown>): DraftInput & { version: number } {
944	  const fields = validateDraftInput(data);
945	  if (typeof data.version !== 'number' || !Number.isInteger(data.version) || data.version < 0) {
946	    throw new HttpError(400, 'version must be a non-negative integer');
947	  }
948	  return { ...fields, version: data.version };
949	}
