1000	        if (fields.version !== current.version) {
1001	          // 409 carries the currently saved article for side-by-side comparison.
1002	          const conflict = new HttpError(409, 'a newer version of this article has been saved');
1003	          (conflict as HttpError & { article?: Article }).article = current;
