1	// End-to-end regression coverage for the homepage draft-save race:
2	// after clicking save, the user keeps typing while waiting for the response.
3	// Those later keystrokes must neither be lost when the save succeeds nor be
4	// falsely reported as saved. Scenarios exercise the real form, status text,
5	// draft list, a second save and reopening the draft — never just the API.
6	//
7	// Run: node test/run.mjs   (CHROME_BIN can override the browser executable)
8	import assert from 'node:assert/strict';
9	import { readFileSync, writeFileSync } from 'node:fs';
10	import { join } from 'node:path';
11	import { setTimeout as sleep } from 'node:timers/promises';
12	import { Browser } from './cdp.mjs';
13	import { TestServer } from './server.mjs';
14	import { RawHttp, splitFrames } from './httpraw.mjs';
15	import * as ui from './ui.mjs';
16	
17	const tests = [];
18	function test(name, fn) { tests.push({ name, fn }); }
19	
20	// Poll the server directly until it has persisted at least `count` articles.
21	// Used with the save gate's capture mode, where the save request really
22	// reaches the server and only its response is parked in the page.
23	async function waitForServerArticles(server, count) {
24	  const deadline = Date.now() + 5000;
25	  for (;;) {
26	    const articles = await server.listArticles();
27	    if (articles.length >= count) return articles;
28	    if (Date.now() > deadline) throw new Error(`server did not persist ${count} articles in time`);
29	    await sleep(25);
30	  }
31	}
32	
33	async function seed(server, fields) {
34	  const res = await server.api('/api/articles', {
35	    method: 'POST',
36	    body: JSON.stringify({ summary: '', ...fields }),
37	  });
38	  assert.equal(res.status, 201, `seed failed: ${res.status}`);
39	  return (await res.json()).article;
40	}
41	
42	// Seeds happen out-of-band (as if saved in another tab), so the page must
43	// reload its list before the user can click the new draft's 编辑 button.
44	async function seedAndReload(server, page, fields) {
45	  const article = await seed(server, fields);
46	  await ui.reload(page);
47	  return article;
48	}
49	
50	async function freshContext(browser) {
51	  const server = await TestServer.start();
52	  const page = await ui.open(browser, server.url);
53	  return { server, page };
54	}
55	
56	async function closeContext({ server, page }, browser) {
57	  ui.assertNoPageErrors(page);
58	  await browser.closePage(page);
59	  await server.stop();
60	}
61	
62	// Runs one isolated server/page per starting point (editing a draft vs. a
63	// blank create form), so a single scenario can cover both starts without
64	// state from one leaking into the other.
65	async function withIsolatedContext(browser, fn) {
66	  const ctx = await freshContext(browser);
67	  try {
68	    await fn(ctx);
69	  } finally {
70	    await closeContext(ctx, browser);
71	  }
72	}
73	
74	// Body text exercising plain-text fidelity: Chinese, other scripts, newlines,
75	// blank lines and HTML-like markup that must never be parsed or executed.
76	const RICH_BODY = '多行正文第一段\n\n中间空行\n\n中文 English café 日本語 العربية 한국어\n\n'
77	  + '<script>alert(1)</script>\n<img src=x onerror=alert(2)><b>不应加粗</b>\n<div>末段</div>';
78	
79	async function getArticle(server, id) {
80	  const res = await server.api(`/api/articles/${id}`);
81	  assert.equal(res.status, 200);
82	  return (await res.json()).article;
83	}
84	
85	// An out-of-band update, exactly as if another tab saved the draft.
86	async function updateOut(server, id, fields, version) {
87	  const res = await server.api(`/api/articles/${id}`, {
88	    method: 'PUT',
89	    body: JSON.stringify({ summary: '', ...fields, version }),
90	  });
91	  const data = await res.json().catch(() => ({}));
92	  return { status: res.status, article: data.article, error: data.error };
93	}
94	
95	// Puts the page into the post-409 state: it opened v1, holds `mine` in the
96	// form, and another tab has since saved v2, so the page's save is rejected
97	// with the side-by-side conflict comparison.
98	async function stageStaleConflict(server, page, v1, mine, v2) {
99	  const article = await seedAndReload(server, page, v1);
100	  await ui.clickEdit(page, v1.title);
101	  await ui.waitLoadedDraft(page);
102	  await ui.fill(page, mine);
103	  const up = await updateOut(server, article.id, v2, 1);
104	  assert.equal(up.status, 200, `other-tab update should succeed: ${up.status} ${up.error || ''}`);
105	  await ui.clickSave(page);
106	  await ui.waitForStatus(page, '409', 'err');
107	  await ui.waitConflictShown(page);
108	  return { article, saved: up.article };
109	}
110	
111	// The comparison columns render with textContent: markup-like text must appear
112	// verbatim and must not create elements or run handlers (no dialog may fire).
113	async function assertConflictPlainText(page) {
114	  const injected = await page.eval(
115	    `document.querySelectorAll('#conflict-box .ver script,#conflict-box .ver img,#conflict-box .ver b').length`);
116	  assert.equal(injected, 0);
117	  assert.equal(page.dialogs.length, 0);
118	}
119	
120	// ---------------------------------------------------------------------------
121	// 1. Editing an existing draft: save, keep typing during the wait, save again.
122	// ---------------------------------------------------------------------------
123	test('编辑态保存等待期间继续输入：内容保留、只提示未保存字段、再次保存生效、重开一致', async (browser) => {
124	  const ctx = await freshContext(browser);
125	  const { server, page } = ctx;
126	  try {
127	    const a = await seedAndReload(server, page, {
128	      title: '原标题',
129	      summary: '原摘要',
130	      body: '原正文第一段\n\n原正文第二段',
131	    });
132	
133	    // 用户实际操作：打开已有草稿（正文以单篇接口返回为准）。
134	    await ui.clickEdit(page, '原标题');
135	    await ui.waitLoadedDraft(page);
136	    let s = await ui.state(page);
137	    assert.equal(s.saveBtnText, '保存修改');
138	    assert.deepEqual(s.form, { title: '原标题', summary: '原摘要', body: '原正文第一段\n\n原正文第二段' });
139	    assert.equal(s.bannerId, a.id);
140	
141	    // 提交标题、摘要、正文。
142	    await ui.fill(page, {
143	      title: '  修改后的标题  ',
144	      summary: '实际提交的摘要 <b>x</b>',
145	      body: '实际提交的正文第一段\n\n实际提交的正文第二段',
146	    });
147	    await ui.gateOn(page);
148	    await ui.clickSave(page);
149	    await ui.waitSavingPending(page, 1);
150	
151	    // 等待响应期间：标题不动，摘要补写、正文重写（含换行、空行、多语言、类 HTML 文本）。
152	    await ui.fill(page, {
153	      summary: '等待期间补写的摘要',
154	      body: '等待期间的正文\n\n空行保留\n\n中文 English café 日本語 العربية\n\n<html>原样文本</html>',
155	    });
156	    // 保存进行中重复点击不会产生第二次提交。
157	    await ui.clickSave(page);
158	    s = await ui.state(page);
159	    assert.equal(s.saveDisabled, true);
160	    assert.deepEqual(await page.eval(`__qtest.gateState()`), { enabled: true, hits: 1, pending: 1 });
161	    // 成功返回前列表仍是旧内容：不能提前显示尚未保存成功的东西。
162	    assert.equal(s.cards[0].title, '原标题');
163	    assert.equal(s.cards[0].summary, '原摘要');
164	
165	    await ui.releaseSaves(page);
166	    await ui.gateOff(page);
167	    await ui.waitForStatus(page, '尚未保存', 'warn');
168	    s = await ui.state(page);
169	
170	    // 明确指出哪些字段还有未保存修改（标题不在其列）。
171	    assert.match(s.statusText, /但摘要、正文在保存期间又被修改/);
172	    assert.ok(!s.statusText.includes('标题在保存期间'));
173	    // 表单保留等待期间输入的当前值，一个字符都不动。
174	    assert.equal(s.form.title, '修改后的标题'); // 本次提交的标题按规则去首尾空白
175	    assert.equal(s.form.summary, '等待期间补写的摘要');
176	    assert.equal(s.form.body,
177	      '等待期间的正文\n\n空行保留\n\n中文 English café 日本語 العربية\n\n<html>原样文本</html>');
178	    // 仍编辑同一篇草稿。
179	    assert.equal(s.formEditing, true);
180	    assert.equal(s.bannerHidden, false);
181	    assert.equal(s.bannerId, a.id);
182	    assert.equal(s.bannerTitle, '修改后的标题');
183	    assert.equal(s.saveBtnText, '保存修改');
184	    assert.equal(s.saveDisabled, false);
185	    // 列表反映的是本次实际提交并保存的标题与摘要，不是等待期间的新输入。
186	    assert.equal(s.listCount, 1);
187	    assert.equal(s.cards[0].title, '修改后的标题');
188	    assert.equal(s.cards[0].summary, '实际提交的摘要 <b>x</b>');
189	    assert.equal(s.cards[0].editing, true);
190	    // 类 HTML 的摘要按文本渲染，不执行任何标记。
191	    assert.equal(await page.eval(`document.querySelectorAll('#article-list .summary').length`), 1);
192	    assert.equal(await page.eval(`document.querySelector('#article-list .summary b')`), null);
193	
194	    // 服务端状态：同一篇草稿，版本推进，标识/创建时间/状态不变，存的是实际提交内容。
195	    let saved = await (await server.api(`/api/articles/${a.id}`)).json();
196	    assert.equal(saved.article.id, a.id);
197	    assert.equal(saved.article.createdAt, a.createdAt);
198	    assert.equal(saved.article.status, 'draft');
199	    assert.equal(saved.article.version, 2);
200	    assert.equal(saved.article.title, '修改后的标题');
201	    assert.equal(saved.article.summary, '实际提交的摘要 <b>x</b>');
202	    assert.equal(saved.article.body, '实际提交的正文第一段\n\n实际提交的正文第二段');
203	
204	    // 再次点击“保存修改”：刚才保留的内容才成为已保存内容，且不能误报冲突。
205	    await ui.clickSave(page);
206	    await ui.waitForStatus(page, '修改已保存', 'ok');
207	    s = await ui.state(page);
208	    assert.equal(s.conflictHidden, true);
209	    assert.equal(s.cards[0].summary, '等待期间补写的摘要');
210	    saved = await (await server.api(`/api/articles/${a.id}`)).json();
