1	// Page-level helpers for the draft-save regression tests.
2	//
3	// The core of every scenario is a race the product must survive: the user
4	// clicks save (or asks to reload the latest saved content), then keeps typing
5	// while the request is in flight. Real network round-trips are too fast to
6	// type against reliably, so before the page's own scripts run we install three
7	// independent gates on window.fetch:
8	//   - save gate: holds POST/PUT /api/articles calls until the test releases;
9	//   - read gate: holds GET /api/articles/:id calls (the single-article read
10	//     used by “编辑” and by the post-conflict “载入最新内容” button);
11	//   - list gate: holds the initial GET /api/articles. Two modes reproduce the
12	//     first-load race deterministically: 'captured' sends the request at once
13	//     and parks the server's pre-save response (a genuine stale snapshot),
14	//     while 'deferred' does not send until release (so the response already
15	//     contains the just-saved draft). A one-shot list failure (500/network)
16	//     can be parked the same way.
17	// The list gate is armed through URL query parameters before navigation, so it
18	// is in place before the page's own load() runs.
19	//
20	// window.confirm is replaced by a controllable double (accept/cancel/native),
21	// because the reload flow asks the user to choose between keeping the current
22	// input and discarding it. The product itself has no test-only code paths.
23	const INIT_SOURCE = `(function () {
24	  if (window.__qtest) return;
25	  var origFetch = window.fetch.bind(window);
26	  var saveGate = { enabled: false, hits: 0, pending: [], capture: false };
27	  var readGate = { enabled: false, hits: 0, pending: [] };
28	  // null = off; 404/500 = respond with that status once; 'network' = reject once.
29	  var failNextRead = null;
30	
31	  // Armed via URL query (?__qtest_list_hold=captured|deferred,
32	  // ?__qtest_list_fail=500|network) so they are active before the page
33	  // script's first load() runs. Consumed once on installation.
34	  var qp = new URLSearchParams(location.search);
35	  var holdMode = qp.get('__qtest_list_hold');
36	  var failNextList = qp.get('__qtest_list_fail');
37	  // Consume the arming parameters so a later ordinary reload does not re-arm.
38	  if (holdMode !== null || failNextList !== null) {
39	    try { window.history.replaceState(null, '', location.pathname); } catch (e) { /* ignore */ }
40	  }
41	  var listGate = {
42	    enabled: holdMode !== null || failNextList !== null,
43	    hits: 0,
44	    pending: [],
45	    captured: 0,
46	    mode: holdMode === 'captured' ? 'captured' : 'deferred'
47	  };
48	
49	  function methodOf(init) { return ((init && init.method) || 'GET').toUpperCase(); }
50	  function pathOf(input) {
51	    var url = typeof input === 'string' ? input : ((input && input.url) || '');
52	    return url.split('?')[0];
53	  }
54	  function isSaveCall(path, method) {
55	    if (method !== 'POST' && method !== 'PUT') return false;
56	    return path === '/api/articles' || /^\\/api\\/articles\\/[^/]+$/.test(path);
57	  }
58	  function isItemRead(path, method) {
59	    return method === 'GET' && /^\\/api\\/articles\\/[^/]+$/.test(path);
60	  }
61	  function isListRead(path, method) {
62	    return method === 'GET' && path === '/api/articles';
63	  }
64	  function hold(gate, input, init) {
65	    gate.hits++;
66	    return new Promise(function (resolve) {
67	      gate.pending.push(function () { resolve(origFetch(input, init)); });
68	    });
69	  }
70	  function releaseGate(gate) {
71	    var pending = gate.pending;
72	    gate.pending = [];
73	    pending.forEach(function (run) { run(); });
74	    return pending.length;
75	  }
76	
77	  function failureResponse(mode) {
78	    var body = JSON.stringify({
79	      error: mode === 404 ? '模拟失败：该草稿已不存在' : '模拟失败：单篇读取暂时不可用'
80	    });
81	    return new Response(body, {
82	      status: mode,
83	      headers: { 'content-type': 'application/json' }
84	    });
85	  }
86	  // A single-article read may be parked by the read gate and/or fail once.
87	  // When both are armed the call parks; the failure is consumed at release so
88	  // the test can type during the wait before the error response arrives.
89	  function runItemRead(input, init) {
90	    if (failNextRead !== null) {
91	      var mode = failNextRead;
92	      failNextRead = null;
93	      if (mode === 'network') return Promise.reject(new Error('模拟的网络连接中断'));
94	      return Promise.resolve(failureResponse(mode));
95	    }
96	    return origFetch(input, init);
97	  }
98	
99	  function listFailureResult(mode) {
100	    if (mode === 'network') {
101	      return Promise.reject(new Error('模拟的网络连接中断'));
102	    }
103	    return Promise.resolve(new Response(JSON.stringify({
104	      error: '模拟失败：文章列表暂时不可用'
105	    }), { status: Number(mode), headers: { 'content-type': 'application/json' } }));
106	  }
107	
108	  // Initial list fetch. With a parked failure the response (or rejection) is
109	  // delivered at release. In 'captured' mode the request goes out immediately
110	  // and the real pre-save Response is held back; in 'deferred' mode the request
111	  // itself waits for release, so the server answers from its current data.
112	  function runListRead(input, init) {
113	    listGate.hits++;
114	    var capturedPromise = null;
115	    if (listGate.mode === 'captured' && failNextList === null) {
116	      capturedPromise = origFetch(input, init);
117	      capturedPromise.then(function () { listGate.captured++; },
118	        function () { listGate.captured++; });
119	    }
120	    return new Promise(function (resolve, reject) {
121	      listGate.pending.push(function () {
122	        if (failNextList !== null) {
123	          var mode = failNextList;
124	          failNextList = null;
125	          listFailureResult(mode).then(resolve, reject);
126	          return;
127	        }
128	        if (capturedPromise) { resolve(capturedPromise); return; }
129	        resolve(origFetch(input, init));
130	      });
131	    });
132	  }
133	
134	  window.fetch = function (input, init) {
135	    var path = pathOf(input);
136	    var method = methodOf(init);
137	    if (isListRead(path, method)) {
138	      if (listGate.enabled) return runListRead(input, init);
139	      return origFetch(input, init);
140	    }
141	    if (isItemRead(path, method)) {
142	      if (readGate.enabled) {
143	        readGate.hits++;
144	        return new Promise(function (resolve) {
145	          readGate.pending.push(function () { resolve(runItemRead(input, init)); });
146	        });
147	      }
148	      return runItemRead(input, init);
149	    }
150	    if (saveGate.enabled && isSaveCall(path, method)) {
151	      if (saveGate.capture) {
152	        // capture 模式：请求立即真实发往服务端（保存会落库），只把响应扣在
153	        // 页面里，用于复现“服务端已保存、列表结果先于创建响应到达页面”。
154	        saveGate.hits++;
155	        var capturedSave = origFetch(input, init);
156	        return new Promise(function (resolve, reject) {
157	          saveGate.pending.push(function () { capturedSave.then(resolve, reject); });
158	        });
159	      }
160	      return hold(saveGate, input, init);
161	    }
162	    return origFetch(input, init);
163	  };
164	
165	  // Deterministic confirm double: 'accept' = 放弃当前输入, 'cancel' = 保留,
166	  // 'native' = fall through to the browser dialog (the harness auto-accepts
167	  // unexpected native dialogs and then fails the scenario).
168	  var nativeConfirm = typeof window.confirm === 'function' ? window.confirm.bind(window)
169	    : function () { return true; };
170	  var confirmBox = { mode: 'native', calls: [] };
171	  window.confirm = function (message) {
172	    confirmBox.calls.push(String(message));
173	    if (confirmBox.mode === 'accept') return true;
174	    if (confirmBox.mode === 'cancel') return false;
175	    return nativeConfirm(String(message));
176	  };
177	
178	  function byId(id) { return document.getElementById(id); }
179	  // Go through the prototype value setter so React-style change detection and
180	  // the page's input listeners see a genuine user edit.
181	  function setValue(id, value) {
182	    var node = byId(id);
183	    var proto = node.tagName === 'TEXTAREA'
184	      ? window.HTMLTextAreaElement.prototype
185	      : window.HTMLInputElement.prototype;
186	    Object.getOwnPropertyDescriptor(proto, 'value').set.call(node, value);
187	    node.dispatchEvent(new Event('input', { bubbles: true }));
188	    node.dispatchEvent(new Event('change', { bubbles: true }));
189	  }
190	  function releaseGate(gate) {
191	    var pending = gate.pending;
192	    gate.pending = [];
193	    pending.forEach(function (run) { run(); });
194	    return pending.length;
195	  }
196	  function gateView(gate) {
197	    return { enabled: gate.enabled, hits: gate.hits, pending: gate.pending.length };
198	  }
199	  window.__qtest = {
200	    set: function (id, value) { setValue(id, value); },
201	    click: function (id) { byId(id).click(); },
202	    clickEdit: function (title) {
203	      var cards = document.querySelectorAll('#article-list article.draft');
204	      for (var i = 0; i < cards.length; i++) {
205	        var h3 = cards[i].querySelector('h3');
206	        var text = h3 && h3.firstChild ? h3.firstChild.nodeValue : '';
207	        if (text === title) { cards[i].querySelector('button').click(); return true; }
208	      }
209	      return false;
210	    },
211	    clickConflictAction: function (label) {
212	      var btns = document.querySelectorAll('#conflict-box .actions button');
213	      for (var i = 0; i < btns.length; i++) {
214	        if (btns[i].textContent === label) { btns[i].click(); return true; }
215	      }
216	      return false;
217	    },
218	    gateOn: function () { saveGate.enabled = true; saveGate.hits = 0; },
219	    gateOff: function () { saveGate.enabled = false; saveGate.capture = false; },
220	    gateCaptureOn: function () { saveGate.enabled = true; saveGate.capture = true; saveGate.hits = 0; },
221	    release: function () { return releaseGate(saveGate); },
222	    gateState: function () { return gateView(saveGate); },
223	    readGateOn: function () { readGate.enabled = true; readGate.hits = 0; },
224	    readGateOff: function () { readGate.enabled = false; },
225	    releaseReads: function () { return releaseGate(readGate); },
226	    readGateState: function () { return gateView(readGate); },
227	    armReadFailure: function (mode) { failNextRead = mode; },
228	    readFailureArmed: function () { return failNextRead; },
229	    listGateOn: function (mode) {
230	      listGate.enabled = true;
231	      listGate.mode = mode === 'captured' ? 'captured' : 'deferred';
232	      listGate.hits = 0;
233	      listGate.captured = 0;
234	    },
235	    listGateOff: function () { listGate.enabled = false; },
236	    releaseList: function () { return releaseGate(listGate); },
237	    listGateState: function () {
238	      var view = gateView(listGate);
239	      view.captured = listGate.captured;
240	      view.mode = listGate.mode;
241	      return view;
242	    },
243	    armListFailure: function (mode) { failNextList = mode; },
244	    confirmMode: function (mode) { confirmBox.mode = mode; },
245	    confirmReset: function () { confirmBox.calls = []; },
246	    confirmState: function () {
247	      return { mode: confirmBox.mode, calls: confirmBox.calls.slice() };
248	    }
249	  };
250	  window.__snap = function () {
251	    function v(id) { return document.getElementById(id).value; }
252	    var status = document.getElementById('status');
253	    var banner = document.getElementById('edit-banner');
254	    var cards = Array.prototype.map.call(
255	      document.querySelectorAll('#article-list article.draft'),
256	      function (card) {
257	        var h3 = card.querySelector('h3');
258	        var sum = card.querySelector('.summary');
259	        var btn = card.querySelector('.actions button');
260	        return {
261	          title: h3 && h3.firstChild ? h3.firstChild.nodeValue : '',
262	          summary: sum ? sum.textContent : null,
263	          editing: !!card.querySelector('.editing-tag'),
264	          editBtnText: btn ? btn.textContent : '',
265	          editBtnDisabled: btn ? btn.disabled : null
266	        };
267	      });
268	    var code = banner.querySelector('code');
269	    var meta = banner.querySelector('.meta');
270	    return {
271	      form: { title: v('title'), summary: v('summary'), body: v('body') },
272	      fieldsEditable: {
273	        title: !byId('title').disabled,
274	        summary: !byId('summary').disabled,
275	        body: !byId('body').disabled
276	      },
277	      saveBtnText: document.getElementById('save-btn').textContent,
278	      saveDisabled: document.getElementById('save-btn').disabled,
279	      cancelHidden: document.getElementById('cancel-btn').hidden,
280	      formEditing: document.getElementById('draft-form').classList.contains('editing'),
281	      bannerHidden: banner.hidden,
282	      bannerTitle: code ? code.textContent : null,
283	      bannerId: meta ? (meta.textContent.split('标识：')[1] || '') : '',
284	      statusText: status.textContent,
285	      statusKind: (status.className.match(/\\b(ok|err|warn)\\b/) || [])[1] || '',
286	      conflictHidden: document.getElementById('conflict-box').hidden,
287	      cards: cards,
288	      listCount: cards.length,
289	      listBusy: document.getElementById('article-list').getAttribute('aria-busy') !== 'false',
290	      listNoticeHidden: document.getElementById('list-notice').hidden,
291	      listNotice: document.getElementById('list-notice').textContent,
292	      emptyTip: document.getElementById('empty-tip').textContent
293	    };
294	  };
295	})();`;
