307	// Opens the homepage with the initial GET /api/articles parked by the list
308	// gate, before the page's own load() has handled any response.
309	//   hold: 'captured' (request already answered by the server with the current
310	//   data, response is held in the page) or 'deferred' (request not sent yet);
311	//   fail: when set ('500' | 'network'), the parked call fails on release.
312	export async function openWithListHeld(browser, baseUrl, { hold = 'deferred', fail = null } = {}) {
313	  const params = new URLSearchParams();
314	  if (fail) params.set('__qtest_list_fail', String(fail));
315	  else params.set('__qtest_list_hold', hold);
