483	export function assertNoPageErrors(page) {
484	  if (page.pageErrors.length) {
485	    throw new Error(`uncaught page errors:\n${page.pageErrors.join('\n')}`);
486	  }
487	  const errors = page.consoleMessages.filter((m) => m.type === 'error');
488	  if (errors.length) {
489	    throw new Error(`console errors:\n${errors.map((m) => m.text).join('\n')}`);
490	  }
491	  if (page.dialogs.length) {
492	    throw new Error(`unexpected native confirm/alert dialogs (dirty-guard fired?):\n${page.dialogs.join('\n---\n')}`);
493	  }
494	}
