test('打开另一篇草稿：有未保存内容先询问；取消不读取且输入/编辑状态不变，确认才开始读取', async (browser) => {
  await withIsolatedContext(browser, async ({ server, page }) => {

    assert.equal((await getArticle(server, target.id)).body, '目标正文');
