    };
    const v2 = { title: '对方新标题', summary: '对方新摘要', body: '对方新正文' };
    const { article, saved } = await stageStaleConflict(server, page, v1, mine, v2);

    // 对照可见时点击取消编辑并选择不退出：当前输入与双方对照原样保留。
    await ui.setConfirm(page, 'cancel');
